  const [page, setPage] = useState(0);
  const PAGE_SIZE = 20; // Example page size

  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchSuppliers = async (reset = false) => {
    if (companyId === 0) return;
    setLoading(true);
    try {
      const allData = await getAllSuppliers(companyId);
      const filteredData = searchText
        ? allData.filter(s =>
            s.supplierName.toLowerCase().includes(searchText.toLowerCase()) ||
            (s.contactName && s.contactName.toLowerCase().includes(searchText.toLowerCase()))
          )
        : allData;

      if (reset) {
        setSuppliers(filteredData.slice(0, PAGE_SIZE));
        setPage(1);
        setInfiniteScrollDisabled(filteredData.length <= PAGE_SIZE);
      } else {
        setSuppliers(prev => {
          const newSuppliers = filteredData.slice(prev.length, prev.length + PAGE_SIZE);
          const combined = [...prev, ...newSuppliers];
          setInfiniteScrollDisabled(combined.length >= filteredData.length);
          return combined;
        });
        setPage(prev => prev + 1);
      }
    } catch (err) {
      setError((err as Error).message || 'Error al cargar proveedores');
